cat > "$TMPDIR/undef.py" <<'EOF'
import ast, builtins, sys, pathlib
B=set(dir(builtins))|{'__file__','__name__','__class__'}
for p in pathlib.Path(sys.argv[1]).rglob('*.py'):
    t=ast.parse(p.read_text())
    defined=set(B)
    for n in ast.walk(t):
        if isinstance(n,(ast.Import,ast.ImportFrom)):
            for a in n.names: defined.add((a.asname or a.name).split('.')[0])
        elif isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):
            defined.add(n.name)
            for a in n.args.args+n.args.kwonlyargs+n.args.posonlyargs if hasattr(n,'args') else []: defined.add(a.arg)
            if hasattr(n,'args'):
                if n.args.vararg: defined.add(n.args.vararg.arg)
                if n.args.kwarg: defined.add(n.args.kwarg.arg)
        elif isinstance(n,ast.Name) and isinstance(n.ctx,(ast.Store,ast.Del)): defined.add(n.id)
        elif isinstance(n,ast.arg): defined.add(n.arg)
        elif isinstance(n,ast.ExceptHandler) and n.name: defined.add(n.name)
        elif isinstance(n,(ast.Global,ast.Nonlocal)): defined.update(n.names)
        elif hasattr(ast,'MatchAs') and isinstance(n,ast.MatchAs) and n.name: defined.add(n.name)
    for n in ast.walk(t):
        if isinstance(n,ast.Name) and isinstance(n.ctx,ast.Load) and n.id not in defined:
            print(f"{p}:{n.lineno}: {n.id}")
EOF
python3 -I "$TMPDIR/undef.py" flask_admin

